{"formatVersion":3,"title":"Coffee counter","description":"Count your cups of coffee and beep each time you add a cup","capabilities":["audio.tone"],"capabilityResults":false,"stateSchema":{"count":"number"},"initialState":{"count":0},"behaviorBindings":{"add":"add","reset":"reset","count":[0,0]},"ui":{"type":"column","children":[{"type":"section","text":"Today's cups","children":[{"type":"metric","text":"Cups today","bind":"count","style":{"emphasis":"number"}},{"type":"row","children":[{"type":"button","text":"Add cup","action":"add","variant":"filled"},{"type":"button","text":"Undo","action":"undo","variant":"outlined"}]}]},{"type":"button","text":"Reset","action":"reset","variant":"text"}]},"source":"const state = input.state;
const event = input.event;

if (event.type === 'preview' || event.type === 'render') {
  return {state: state};
}

if (event.type === 'action') {
  const count = typeof state.count === 'number' ? state.count : 0;

  if (event.actionId === 'add') {
    const next = count + 1;
    if (next > 9007199254740991) {
      return {state: state};
    }
    return {
      state: Object.assign({}, state, {count: next}),
      effects: [{id: 'beep', capability: 'audio.tone', args: {tone: 'beep', durationMillis: 120}}]
    };
  }

  if (event.actionId === 'undo') {
    return {state: Object.assign({}, state, {count: Math.max(0, count - 1)})};
  }

  if (event.actionId === 'reset') {
    return {state: Object.assign({}, state, {count: 0})};
  }
}

return {state: state};"}
